prelude_js:
// 惩罚常数 C = 4εγ/(1−γ)²：γ=0.9 → 360ε；γ=0.99 → 39600ε；γ=0.999 → 3996000ε。
// D_TV 的两种写法只有在「只有一个分量上升」时才相等；
// 反例：p=(0.4,0.4,0.1,0.1) → q=(0.1,0.1,0.4,0.4)，L∞=0.30 而 ½L1=0.60。
// 本片数字由独立脚本核算。
function penC(g){return 4*g/Math.pow(1-g,2);}
function linf(p,q){var m=0,i;for(i=0;i<p.length;i++)m=Math.max(m,Math.abs(p[i]-q[i]));return m;}
function tvd(p,q){var s=0,i;for(i=0;i<p.length;i++)s+=Math.abs(p[i]-q[i]);return s/2;}
// MM 玩具（KP5/KP6/KP7 共用，数字由 scratchpad 脚本独立核算）：
// V(x)=1-4(x-0.62)^2, x_i=0.20, V(x_i)=0.2944, 切线斜率 3.36。
// 切在 x_i 的下界最大化后 V→0.8236(+0.5292)；切在 0.05 的合法下界最大化后 V→0.0239(-0.2705)。
function Vtoy(x){return 1-4*Math.pow(x-0.62,2);}
function vx(x){return 320+x/0.7*680;}
function vy(v){return 440-(v+0.6)/1.65*250;}
// 最优步长 = 切线斜率/(2C)，所以步长与 C 成反比。
function stepOf(C){return 3.36/(2*C);}

